// Кейс: .qa/tests/monitoring/MON-013.md · план: .qa/e2e-app/specs/app.md (1.10)
// «בדיקת בטיחות»: камера и уведомления Eitan разрешены → строка «הרשאות מצלמה והתרעות» без предупреждения и не кнопка.
// РУЧНОЕ ПРЕДУСЛОВИЕ: в настройках iPhone у приложения включены камера и уведомления (обычное состояние телефона).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSafetyCheck } from '../../lib/banci.mjs';

export const name = 'בדיקת בטיחות: всё разрешено → строка «הרשאות מצלמה והתרעות» ✓, не кнопка, без «אשרו…» #2bc13b @iphone @app @prod-safe';

export default async function (app) {
  await openSafetyCheck(app);
  await app.waitFor(by.begins('הרשאות מצלמה והתרעות'), { timeout: 20000, what: 'строка «הרשאות מצלמה והתרעות»' });

  if (await app.exists(by.contains('אשרו התראות בהגדרות הטלפון')) || await app.exists(by.contains('אשרו גישה למצלמה בהגדרות הטלפון'))) {
    skip('у приложения выключены уведомления или камера в настройках iPhone — включить вручную (Настройки → приложение) и перезапустить; проверка «выключено» — тест 1.11');
  }

  // Строка в состоянии ✓ — не нажимается: среди совпадений нет элемента типа Button.
  const buttons = await app.findAll(by.begins('הרשאות מצלמה והתרעות', 'Button'));
  assert(buttons.length === 0, 'при всех разрешениях строка «הרשאות מצלמה והתרעות» не кнопка (traits не Button)');

  await app.restart();
}
